// lookup demo — Tomato (jahdb demo program)
var DATA={"Tomato":"Tomatoes are the garden gateway: full sun, deep regular water, and staking. Start seeds indoors 6 weeks before last frost."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("summer"));

